@functools.cached_property
def fsid(self) -> str:
    from fsspec.utils import tokenize

    from dvc.scm import NoSCM, SCMError

    rev = None
    if not isinstance(self.repo.scm, NoSCM):
        try:
            rev = self.repo.get_rev()
        except SCMError:
            pass

    return "dvcfs_" + tokenize(
        self.repo.url or self.repo.root_dir,
        rev,
    )
